const routeOf=n=>ROUTES.find(r=>r[0]===n);
const routeSvg=(P,pts,o)=>{o=o||{};let segs=[],cur=[];for(let i=0;i<pts.length;i++){if(i&&Math.abs(pts[i][0]-pts[i-1][0])>180){segs.push(cur);cur=[];}cur.push(P.P(pts[i]));}segs.push(cur);
 let s=segs.filter(g=>g.length>1).map(g=>PL(g,{c:o.c||'var(--bad)',sw:o.sw||2.4,dash:o.dash})).join('');const a=P.P(pts[0]);s+=CIR(a[0],a[1],4,{f:o.c||'var(--bad)',s:'var(--card)',sw:1});
 const last=segs[segs.length-1];if(last.length>1){const n=last.length;s+=HEAD(last[n-1][0],last[n-1][1],last[n-1][0]-last[n-2][0],last[n-1][1]-last[n-2][1],{c:o.c||'var(--bad)',hs:8});}return s;};
