/* ---------------- widgets ---------------- */
function onTheory(root){
 const w=root.querySelector('#w-routes');
 if(w){w.innerHTML=`<b>🧭 Маршруты путешественников: выбери героя</b>${BTNS(ROUTES.map((r,i)=>['rt'+i,r[0].replace(/ и .*/,' и др.')]))}<div id="rP" class="fig"></div><div id="rT" style="line-height:1.6;min-height:4em"></div>`;
  let k=0;const g=id=>w.querySelector('#'+id);const u=()=>{const r=ROUTES[k];g('rP').innerHTML=routeMap([r[0]]);g('rT').innerHTML=`<span class="out">${r[0]}</span> · ${r[1]}<br>${r[2]}`;setBtns(w,ROUTES.map((_,i)=>'rt'+i),'rt'+k);};
  ROUTES.forEach((_,i)=>{g('rt'+i).onclick=()=>{k=i;u();};});u();}
 const e=root.querySelector('#w-erat');
 if(e){e.innerHTML=`<b>📐 Опыт Эратосфена: измерь Землю палкой</b>${SL('eA','Угол тени в Александрии:',3,15,0.1,7.2)}${SL('eD','Расстояние между городами:',300,1500,10,800)}<div id="eP" class="fig"></div><div id="eT" style="text-align:center;line-height:1.7"></div>`;
  const g=id=>e.querySelector('#'+id);const u=()=>{const a=+g('eA').value,d=+g('eD').value;g('eAo').textContent=N(a)+'°';g('eDo').textContent=N(d)+' км';const k=360/a,C=k*d;g('eP').innerHTML=figErat(a);
   g('eT').innerHTML=`360° : ${N(a)}° = ${N(rnd(k,2))} → окружность Земли = ${N(rnd(k,2))} · ${N(d)} км = <span class="out">${N(Math.round(C))} км</span><br><span class="small">Настоящая длина экватора — около 40 000 км. ${Math.abs(C-40000)<2000?'Почти точно, как у Эратосфена!':''}</span>`;};
  g('eA').oninput=u;g('eD').oninput=u;u();}
}

